if.script:
const timeEntryFields = Object.assign({}, timeEntry)
for (const fieldName of Object.keys(timeEntryFields)) {
    const fieldValue = timeEntryFields[fieldName]
    if (fieldValue != null && !(fieldName in context)) globalThis[fieldName] = fieldValue
}

actions.script:
const millisOf = (value) => {
    const text = String(value)
    return /^-?\d+$/.test(text) ? Number(text) : Date.parse(text.length === 10 ? text + 'T00:00:00Z' : text)
}
const hourMillis = 60 * 60 * 1000
const hasHours = hours != null && !toDecimal(hours).isZero()
const hasBreak = breakHours != null && !toDecimal(breakHours).isZero()
const hoursMillis = hasHours ? toDecimal(hours).multiply(hourMillis).toNumber() : 0
const breakMillis = hasBreak ? toDecimal(breakHours).multiply(hourMillis).toNumber() : 0

if (hasHours && fromDate && !thruDate) thruDate = String(Math.trunc(millisOf(fromDate) + hoursMillis + breakMillis))
// at this point if there is no thruDate default to now
if (thruDate == null) thruDate = ec.user.nowTimestamp
if (hasHours && !fromDate && thruDate) fromDate = String(Math.trunc(millisOf(thruDate) - hoursMillis - breakMillis))

fromAfterThru = !!(fromDate && thruDate && millisOf(fromDate) > millisOf(thruDate))
if (!fromAfterThru && hours == null && fromDate && thruDate) {
    hours = toDecimal(millisOf(thruDate) - millisOf(fromDate)).divide(hourMillis).subtract(breakHours ?? 0)
}

const millis = (value) => value == null || value === '' ? null : Number(String(value))
if (!timesheetId && partyId && fromDate != null) {
    ec.message.pushErrors()
    try {
        timesheetId = ec.service.sync().name('mantle.work.TimesheetServices.get#PartyTimesheet').parameters({partyId: partyId,
            date: millis(fromDate)}).call()?.timesheetId || null
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        timesheetId = null
        ec.logger.error(`Time entry of ${partyId}: its week's timesheet was not found or made, the entry goes on none: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
// the lock: the stored entry's timesheet, and the one it goes on
const lockedSheets = {}
const isLocked = (id) => {
    if (!id) return false
    if (!(id in lockedSheets)) {
        const sheet = ec.entity.find('mantle.work.time.Timesheet').condition('timesheetId', id).disableAuthz().one()
        let locked = !!sheet && (sheet.statusId === 'TmshCompleted' || sheet.statusId === 'TmshApproved')
        if (locked) locked = ec.service.sync().name('mantle.work.TimesheetServices.get#TimesheetPolicy').parameters({partyId: sheet.partyId})
                .call()?.policy?.lock !== false
        lockedSheets[id] = locked
    }
    return lockedSheets[id]
}
const stored = timeEntry || null
const storedSheet = stored?.timesheetId || null
const L = (text) => ec.l10n.localize(text)
if (!stored) {
    if (isLocked(timesheetId)) ec.message.addError(L('That week is submitted: its time is locked until it is returned or reopened'))
    return
}
const same = (a, b) => {
    if (a == null || a === '') return b == null || b === ''
    if (b == null || b === '') return false
    const na = Number(String(a)), nb = Number(String(b))
    return !Number.isNaN(na) && !Number.isNaN(nb) ? Math.abs(na - nb) < 0.0001 : String(a) === String(b)
}
const changed = !same(fromDate, stored.fromDate) || !same(thruDate, stored.thruDate) || !same(hours, stored.hours) || !same(breakHours, stored.breakHours)
        || !same(workEffortId, stored.workEffortId) || !same(partyId, stored.partyId) || !same(workTypeEnumId, stored.workTypeEnumId)
        || !same(comments, stored.comments) || !same(pieceCount, stored.pieceCount)
const moved = (timesheetId || null) !== storedSheet
if ((isLocked(storedSheet) && (changed || moved)) || (moved && isLocked(timesheetId)))
    ec.message.addError(ec.resource.expand('Time entry ${id} is on a submitted week: it is locked until the week is returned or reopened', '', {id: stored.timeEntryId}))

if (pieceAmountTotal != null && !toDecimal(pieceAmountTotal).isZero()) {
    if (pieceRateAmount?.rateTypeEnumId === 'RatpPiecePlusHour') {
        amountTotal = toDecimal(hourlyAmountTotal ?? 0).add(pieceAmountTotal)
        amount = amountTotal
        quantity = toDecimal(1)
    } else if (toDecimal(hourlyAmountTotal ?? 0).compare(pieceAmountTotal) > 0) {
        amountTotal = hourlyAmountTotal
        amount = hourlyAmount
        quantity = hours
    } else {
        amountTotal = pieceAmountTotal
        amount = pieceAmount
        quantity = pieceCount
    }
} else {
    amountTotal = hourlyAmountTotal
    amount = hourlyAmount
    quantity = hours
}

const findMaximalMatch = (mapList, fieldsByPriority) => {
    const fieldNames = Object.keys(fieldsByPriority)
    const numFields = fieldNames.length
    let highScore = -1
    let highMap = null
    for (const curMap of mapList) {
        let curScore = 0
        let skipMap = false
        for (let i = 0; i < numFields; i++) {
            const curValue = curMap[fieldNames[i]]
            // a null value in the rate allows any match value
            if (curValue == null) continue
            if (curValue !== fieldsByPriority[fieldNames[i]]) { skipMap = true; break }
            curScore += (numFields - i) + numFields
        }
        if (skipMap) continue
        if (curScore > highScore) { highScore = curScore; highMap = curMap }
    }
    return highMap
}
const matchFields = {workTypeEnumId: workTypeEnumId, payGradeId: payGradeId, emplPositionClassId: emplPositionClassId}

partyRateAmountToUse = (partyRaList != null && partyRaList.length) ? findMaximalMatch(partyRaList, matchFields) : null

// Do a maximal match on the rates that do not have a partyId.
nonPartyRaList = rateAmountList.filter((ra) => ra.partyId == null)
nonPartyRateAmountToUse = findMaximalMatch(nonPartyRaList, matchFields)

service-call.in-map:
{partyId:party.partyId, rateTypeEnumId:rateTypeEnumId, emplPositionClassId:emplPositionClassId,
                        clientPartyId:clientPartyId, fromDate:fromDate, thruDate:thruDate,
                        hours:hours, pieceCount:pieceCount}

actions.script:
rowList = []; rowCount = 0; totals = null
const L = (text) => ec.l10n.localize(text)
const cf = ec.entity.conditionFactory
const me = ec.user.userAccount?.partyId || null
const isAdmin = !!ec.user.userId && ec.user.isInGroup('ADMIN')
ratesShown = !!withRates && (isAdmin || ec.user.hasPermission('TIME_ENTRY_RATE'))
const size = Math.max(1, Math.min(Number(pageSize) || 50, 500))
const index = Math.max(0, Number(pageIndex) || 0)
const toMillis = (value) => value == null || value === '' ? null : (value instanceof Date ? value.getTime() : (/^-?\d+$/.test(String(value)) ? Number(String(value)) : Date.parse(String(value))))
const num = (value) => value == null || value === '' ? null : Number(String(value))
const round = (value) => Math.round(value * 100) / 100
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    // ===== who the user sees
    const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
    // a client contact sees no time here (impl-projects.md P10: shared hours are the project's own view, without rates)
    if (vis.isClient) { pageIndex = 0; pageSize = size; pageMaxIndex = 0; pageRangeLow = 0; pageRangeHigh = 0; return }
    let anyApprover = false
    if (!isAdmin && ec.user.hasPermission('TIMESHEET_APPROVE')) anyApprover = ec.service.sync().name('mantle.work.TimesheetServices.get#TimesheetPolicy')
            .call()?.policy?.approvers === 'any'
    seesAll = isAdmin || anyApprover
    const seen = []
    if (!seesAll) {
        if (!me) { pageIndex = 0; pageSize = size; pageMaxIndex = 0; pageRangeLow = 0; pageRangeHigh = 0; return }
        seen.push(cf.makeCondition('partyId', 'equals', me))
        const managed = Array.from(vis.managedProjectIds || [])
        if (managed.length) {
            seen.push(cf.makeCondition('rootWorkEffortId', 'in', managed))
            seen.push(cf.makeCondition('workEffortId', 'in', managed))
        }
        const reports = Array.from(new Set(Array.from(ec.entity.find('mantle.party.PartyRelationship').condition('relationshipTypeEnumId', 'PrtManager')
                .condition('fromPartyId', me).conditionDate('fromDate', 'thruDate', null).list()).map((row) => row.toPartyId)))
        if (reports.length) seen.push(cf.makeCondition('partyId', 'in', reports))
    }
    // ===== the find
    const conds = []
    if (seen.length) conds.push(cf.makeCondition(seen, 'or'))
    if (partyId) conds.push(cf.makeCondition('partyId', 'equals', partyId))
    if (rootWorkEffortId) conds.push(cf.makeCondition([cf.makeCondition('rootWorkEffortId', 'equals', rootWorkEffortId),
        cf.makeCondition('workEffortId', 'equals', rootWorkEffortId)], 'or'))
    if (workEffortId) conds.push(cf.makeCondition('workEffortId', 'equals', workEffortId))
    if (noWorkItem) conds.push(cf.makeCondition('workEffortId', 'is-null', null))
    if (clientPartyId) conds.push(cf.makeCondition('clientPartyId', 'equals', clientPartyId))
    if (workTypeEnumId) conds.push(cf.makeCondition('workTypeEnumId', 'equals', workTypeEnumId))
    if (billable === 'Y') conds.push(cf.makeCondition('rateTypeEnumId', 'not-equals', 'RatpNoCharge', true))
    if (billable === 'N') conds.push(cf.makeCondition('rateTypeEnumId', 'equals', 'RatpNoCharge'))
    if (clientInvoiced === 'Y') conds.push(cf.makeCondition('invoiceId', 'is-not-null', null))
    if (clientInvoiced === 'N') conds.push(cf.makeCondition('invoiceId', 'is-null', null))
    if (workerInvoiced === 'Y') conds.push(cf.makeCondition('vendorInvoiceId', 'is-not-null', null))
    if (workerInvoiced === 'N') conds.push(cf.makeCondition('vendorInvoiceId', 'is-null', null))
    if (fromDate != null) conds.push(cf.makeCondition('fromDate', 'greater-equals', new Date(toMillis(fromDate))))
    if (thruDate != null) conds.push(cf.makeCondition('fromDate', 'less-than', new Date(toMillis(thruDate))))
    if (text && String(text).trim()) conds.push(cf.makeCondition('comments', 'like', '%' + String(text).trim() + '%', false, true))
    if (timeEntryIds != null) {
        const ids = Array.from(timeEntryIds).map(String).filter((id) => id)
        conds.push(ids.length ? cf.makeCondition('timeEntryId', 'in', ids) : cf.makeCondition('timeEntryId', 'equals', '_NA_'))
    }
    // the week's status: the timesheets of each status, as an IN on timesheetId
    if (['open', 'returned', 'submitted', 'approved', 'locked'].includes(sheetStatus)) {
        const statuses = {submitted: ['TmshCompleted'], approved: ['TmshApproved'], locked: ['TmshCompleted', 'TmshApproved']}[sheetStatus]
        if (statuses) {
            const sheetIds = Array.from(ec.entity.find('mantle.work.time.Timesheet').condition('statusId', 'in', statuses).selectField('timesheetId')
                    .limit(20000).list()).map((row) => row.timesheetId)
            conds.push(sheetIds.length ? cf.makeCondition('timesheetId', 'in', sheetIds) : cf.makeCondition('timesheetId', 'equals', '_NA_'))
        } else if (sheetStatus === 'returned') {
            const sheetIds = Array.from(ec.entity.find('mantle.work.time.Timesheet').condition(cf.makeCondition('statusId', 'equals', 'TmshInProcess', true))
                    .condition('comments', 'is-not-null', null).selectField('timesheetId').limit(20000).list()).map((row) => row.timesheetId)
            conds.push(sheetIds.length ? cf.makeCondition('timesheetId', 'in', sheetIds) : cf.makeCondition('timesheetId', 'equals', '_NA_'))
        } else {
            const closedIds = Array.from(ec.entity.find('mantle.work.time.Timesheet').condition('statusId', 'in', ['TmshCompleted', 'TmshApproved'])
                    .selectField('timesheetId').limit(20000).list()).map((row) => row.timesheetId)
            if (closedIds.length) conds.push(cf.makeCondition([cf.makeCondition('timesheetId', 'is-null', null),
                cf.makeCondition('timesheetId', 'not-in', closedIds)], 'or'))
        }
    }
    const where = conds.length ? cf.makeCondition(conds, 'and') : null
    const view = 'mantle.work.time.TimeEntryAndWorkEffort'
    const findOf = () => { const find = ec.entity.find(view); return where ? find.condition(where) : find }
    rowCount = findOf().count()
    const orders = {fromDate: 'fromDate', hours: 'hours', partyId: 'partyId', workEffortId: 'workEffortId'}
    const wanted = String(orderByField || '-fromDate')
    const desc = wanted.startsWith('-')
    const orderField = orders[wanted.replace(/^[-+]/, '')] || 'fromDate'
    let find = findOf().orderBy((desc ? '-' : '') + orderField)
    if (orderField !== 'fromDate') find = find.orderBy('-fromDate')
    find = find.orderBy('timeEntryId')
    if (!pageNoLimit) find = find.offset(index * size).limit(size)
    else find = find.limit(5000)
    const page = Array.from(find.list()).map((row) => row.getMap())
    pageIndex = pageNoLimit ? 0 : index
    pageSize = pageNoLimit ? Math.max(page.length, 1) : size
    pageMaxIndex = pageNoLimit ? 0 : Math.max(0, Math.ceil(rowCount / size) - 1)
    pageRangeLow = rowCount ? pageIndex * pageSize + 1 : 0
    pageRangeHigh = rowCount ? Math.min(rowCount, pageIndex * pageSize + page.length) : 0

    // ===== the rows' names, timesheets and the policy's lock of each person
    const nameCache = {}
    const nameOf = (id) => {
        if (!id) return ''
        if (!(id in nameCache)) {
            const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).one()
            nameCache[id] = party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || party.pseudoId || id) : id
        }
        return nameCache[id]
    }
    const projectNames = {}
    const projectName = (id) => {
        if (!id) return ''
        if (!(id in projectNames)) projectNames[id] = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id).one()?.workEffortName || id
        return projectNames[id]
    }
    const sheetIds = Array.from(new Set(page.map((row) => row.timesheetId).filter((id) => id)))
    const sheets = {}
    if (sheetIds.length) for (const sheet of ec.entity.find('mantle.work.time.Timesheet').condition('timesheetId', 'in', sheetIds).list()) sheets[sheet.timesheetId] = sheet
    const lockCache = {}
    const lockOf = (person) => {
        if (!(person in lockCache)) lockCache[person] = ec.service.sync().name('mantle.work.TimesheetServices.get#TimesheetPolicy')
                .parameters({partyId: person}).call()?.policy?.lock !== false
        return lockCache[person]
    }
    const typeLabels = {}
    for (const type of ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', 'WorkType').useCache(true).list()) typeLabels[type.enumId] = type.description || type.enumId
    const rateAmounts = {}
    const rateOf = (own, rateAmountId) => {
        if (num(own) != null) return num(own)
        if (!rateAmountId) return null
        if (!(rateAmountId in rateAmounts)) rateAmounts[rateAmountId] = num(ec.entity.find('mantle.humanres.rate.RateAmount').condition('rateAmountId', rateAmountId)
                .useCache(true).one()?.rateAmount)
        return rateAmounts[rateAmountId]
    }
    for (const row of page) {
        const sheet = row.timesheetId ? sheets[row.timesheetId] : null
        const status = sheet?.statusId || 'TmshInProcess'
        const isProject = row.workEffortTypeEnumId === 'WetProject'
        const root = isProject ? row.workEffortId : (row.rootWorkEffortId || null)
        const hours = num(row.hours) ?? 0
        const out = {timeEntryId: row.timeEntryId, partyId: row.partyId, personName: nameOf(row.partyId), workEffortId: row.workEffortId || null,
            workEffortName: row.workEffortName || '', workEffortTypeEnumId: row.workEffortTypeEnumId || null, rootWorkEffortId: root,
            projectName: projectName(root), fromDate: toMillis(row.fromDate), thruDate: toMillis(row.thruDate), running: row.thruDate == null && row.fromDate != null,
            hours: hours, breakHours: num(row.breakHours), workTypeEnumId: row.workTypeEnumId || null, workTypeLabel: row.workTypeEnumId ? (typeLabels[row.workTypeEnumId] || row.workTypeEnumId) : '',
            rateTypeEnumId: row.rateTypeEnumId || null, billable: row.rateTypeEnumId !== 'RatpNoCharge', comments: row.comments || '', clientPartyId: row.clientPartyId || null,
            timesheetId: row.timesheetId || null, sheetStatusId: status, returned: status === 'TmshInProcess' && !!sheet?.comments,
            locked: (status === 'TmshCompleted' || status === 'TmshApproved') && lockOf(row.partyId),
            invoiceId: row.invoiceId || null, vendorInvoiceId: row.vendorInvoiceId || null, invoiced: !!(row.invoiceId || row.vendorInvoiceId)}
        if (ratesShown) {
            // the entry's own hour rate, else its RateAmount's (new entries carry only rateAmountId, impl-projects.md F86)
            out.clientHourRate = rateOf(row.clientHourRate, row.rateAmountId)
            out.vendorHourRate = rateOf(row.vendorHourRate, row.vendorRateAmountId)
            out.clientAmount = out.clientHourRate == null ? null : round(hours * out.clientHourRate)
            out.vendorAmount = out.vendorHourRate == null ? null : round(hours * out.vendorHourRate)
        }
        rowList.push(out)
    }

    // ===== the totals over every match
    if (withTotals) {
        let all = findOf().selectField('timeEntryId').selectField('partyId').selectField('hours').selectField('rateTypeEnumId').selectField('workTypeEnumId')
                .selectField('workEffortId').selectField('workEffortName').selectField('estimatedWorkTime')
        if (ratesShown) all = all.selectField('clientHourRate').selectField('vendorHourRate').selectField('rateAmountId').selectField('vendorRateAmountId')
        const rows = Array.from(all.limit(20000).list())
        const sum = {hours: 0, billableHours: 0, nonBillableHours: 0, entryCount: rows.length, clientAmount: ratesShown ? 0 : null, vendorAmount: ratesShown ? 0 : null}
        const byPerson = {}, byType = {}, byItem = {}
        for (const row of rows) {
            const hours = num(row.hours) ?? 0
            const billed = row.rateTypeEnumId !== 'RatpNoCharge'
            sum.hours += hours
            if (billed) sum.billableHours += hours; else sum.nonBillableHours += hours
            const person = byPerson[row.partyId] || (byPerson[row.partyId] = {partyId: row.partyId, name: nameOf(row.partyId), hours: 0, billableHours: 0})
            person.hours += hours
            if (billed) person.billableHours += hours
            const typeKey = row.workTypeEnumId || ''
            const type = byType[typeKey] || (byType[typeKey] = {workTypeEnumId: row.workTypeEnumId || null, label: row.workTypeEnumId ? (typeLabels[row.workTypeEnumId] || row.workTypeEnumId) : L('No work type'), hours: 0})
            type.hours += hours
            const itemKey = row.workEffortId || ''
            const item = byItem[itemKey] || (byItem[itemKey] = {workEffortId: row.workEffortId || null, name: row.workEffortName || (row.workEffortId ? row.workEffortId : L('No work item')),
                estimate: num(row.estimatedWorkTime), hours: 0})
            item.hours += hours
            if (ratesShown) {
                const clientRate = rateOf(row.clientHourRate, row.rateAmountId)
                const vendorRate = rateOf(row.vendorHourRate, row.vendorRateAmountId)
                if (clientRate != null) sum.clientAmount += round(hours * clientRate)
                if (vendorRate != null) sum.vendorAmount += round(hours * vendorRate)
            }
        }
        const sorted = (map) => Object.values(map).map((entry) => Object.assign(entry, {hours: round(entry.hours)},
                entry.billableHours != null ? {billableHours: round(entry.billableHours)} : {})).sort((a, b) => b.hours - a.hours)
        totals = {hours: round(sum.hours), billableHours: round(sum.billableHours), nonBillableHours: round(sum.nonBillableHours), entryCount: sum.entryCount,
            clientAmount: sum.clientAmount == null ? null : round(sum.clientAmount), vendorAmount: sum.vendorAmount == null ? null : round(sum.vendorAmount),
            byPerson: sorted(byPerson), byWorkType: sorted(byType), byItem: sorted(byItem).slice(0, 50), truncated: rows.length >= 20000}
    }
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

const L = (text, values) => ec.resource.expand(ec.l10n.localize(text), '', values || {})
rowCount = 0; columnMapping = {}; unusedColumns = []; previewList = []; counts = {rows: 0, create: 0, skip: 0, fail: 0, warned: 0}
createdCount = 0; skippedCount = 0; failedCount = 0; hoursImported = 0; failureList = []; warningList = []; resultList = []
const me = ec.user.userAccount?.partyId || null
const defaultPerson = partyId || me

// ===== the text, its records and columns
let content = fileText
if (content == null && (timeEntryFile != null || fileLocation)) {
    const read = ec.service.sync().name('mantle.party.ContactImportServices.read#ContactFileText').parameters({contactFile: timeEntryFile,
        fileLocation: timeEntryFile != null ? null : fileLocation, characterSet: characterSet || 'UTF-8'}).call()
    if (ec.message.hasError()) return
    content = read.text
}
if (content == null || String(content).trim() === '') { ec.message.addError(L('The time file is empty')); return }
content = String(content)
if (content.charCodeAt(0) === 0xFEFF) content = content.substring(1)
const firstLine = content.split(/\r?\n/, 1)[0]
const outside = firstLine.replace(/"[^"]*"/g, '')
const delimiter = [',', ';', '\t'].map((d) => [d, outside.split(d).length]).sort((a, b) => b[1] - a[1])[0][0]
const records = []
let record = [], field = '', quoted = false
for (let i = 0; i < content.length; i++) {
    const ch = content[i]
    if (quoted) {
        if (ch === '"') { if (content[i + 1] === '"') { field += '"'; i++ } else quoted = false } else field += ch
    } else if (ch === '"' && field === '') quoted = true
    else if (ch === delimiter) { record.push(field); field = '' }
    else if (ch === '\n' || ch === '\r') {
        if (ch === '\r' && content[i + 1] === '\n') i++
        record.push(field); field = ''; records.push(record); record = []
    } else field += ch
}
if (field !== '' || record.length) { record.push(field); records.push(record) }
const lines = records.filter((rec) => rec.some((value) => String(value).trim() !== ''))
if (!lines.length) { ec.message.addError(L('The time file has no header line')); return }
const headers = lines[0].map((header) => String(header).trim())
const norm = (text) => String(text).toLowerCase().replace(/[^a-z0-9]/g, '')
// each target by its header words, in order of preference
const aliases = {
    date: ['date', 'day', 'startdate', 'spenton', 'entrydate', 'workdate'],
    person: ['email', 'useremail', 'person', 'username', 'login', 'user', 'worker', 'member', 'employee', 'name'],
    item: ['workitem', 'workitemkey', 'workitemorprojectkey', 'workitemorproject', 'item', 'key', 'task', 'taskkey', 'issue', 'issuekey', 'ticket'],
    project: ['project', 'projectkey'],
    hours: ['hours', 'durationh', 'durationhours', 'durationdecimal', 'hoursspent', 'spenthours', 'duration', 'time'],
    start: ['start', 'starttime', 'from', 'fromtime', 'begin'],
    end: ['end', 'endtime', 'to', 'totime', 'thru', 'thrutime', 'finish'],
    workType: ['worktype', 'activity', 'type', 'category'],
    billable: ['billable', 'isbillable'],
    comment: ['comment', 'comments', 'description', 'notes', 'note', 'details']}
const used = new Set()
const indexOf = {}
for (const [target, words] of Object.entries(aliases)) {
    for (const word of words) {
        const at = headers.findIndex((header, i) => !used.has(i) && norm(header) === word)
        if (at >= 0) { indexOf[target] = at; used.add(at); columnMapping[target] = headers[at]; break }
    }
}
unusedColumns = headers.filter((header, i) => !used.has(i) && header)
if (indexOf.date == null && indexOf.start == null) { ec.message.addError(L('The file has no date column (date, or start with a date)')); return }
if (indexOf.hours == null && (indexOf.start == null || indexOf.end == null)) { ec.message.addError(L('The file has no hours column, nor start and end')); return }
const dataLines = lines.slice(1)
rowCount = dataLines.length
counts.rows = rowCount

// ===== the lookups, cached for the rows
const wasDisabled = ec.artifactExecution.disableAuthz()
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
const visible = new Set(Array.from(vis.visibleProjectIds || []))
const managed = new Set(Array.from(vis.managedProjectIds || []))
const restricted = new Set(Array.from(vis.restrictedItemIds || []))
const cache = {person: {}, item: {}, type: null, access: {}, policy: {}}
const personOf = (value) => {
    const text = String(value || '').trim()
    if (!text) return {partyId: defaultPerson}
    const key = text.toLowerCase()
    if (key in cache.person) return cache.person[key]
    let found = Array.from(ec.entity.find('moqui.security.UserAccount').condition(ec.entity.conditionFactory.makeCondition([
            ec.entity.conditionFactory.makeCondition('username', 'equals', text, true),
            ec.entity.conditionFactory.makeCondition('emailAddress', 'equals', text, true)], 'or')).list()).filter((account) => account.partyId)
    if (!found.length && /\s/.test(text)) {
        const parts = text.split(/\s+/)
        const people = Array.from(ec.entity.find('mantle.party.Person').condition('firstName', 'equals', parts[0], true)
                .condition('lastName', 'equals', parts.slice(1).join(' '), true).list())
        found = people.length === 1 ? [{partyId: people[0].partyId}] : (people.length > 1 ? people : [])
        if (people.length > 1) { cache.person[key] = {error: L('${name} matches several people', {name: text})}; return cache.person[key] }
    }
    const ids = Array.from(new Set(found.map((row) => row.partyId)))
    cache.person[key] = ids.length === 1 ? {partyId: ids[0]} : {error: ids.length ? L('${name} matches several people', {name: text}) : L('No person ${name}', {name: text})}
    return cache.person[key]
}
const itemOf = (value) => {
    const text = String(value || '').trim()
    if (!text) return null
    if (text in cache.item) return cache.item[text]
    let item = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', text).one()
    if (!item && text !== text.toUpperCase()) item = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', text.toUpperCase()).one()
    let result
    if (!item || !['WetTask', 'WetProject'].includes(item.workEffortTypeEnumId)) result = {error: L('No work item or project ${key}', {key: text})}
    else {
        const root = item.workEffortTypeEnumId === 'WetProject' ? item.workEffortId : item.rootWorkEffortId
        const rootItem = root ? ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', root).one() : null
        const seen = !!vis.allProjects || (root && visible.has(root))
        const hidden = item.workEffortTypeEnumId === 'WetTask' && ['WevRestricted', 'WevConfidential'].includes(item.visibilityEnumId)
                && !vis.allProjects && !managed.has(root) && !restricted.has(item.workEffortId)
        if (!root || !seen || hidden) result = {error: L('Work item ${key} is not available', {key: text})}
        else if (rootItem?.isTemplate === 'Y') result = {error: L('${key} is in a template', {key: text})}
        else result = {workEffortId: item.workEffortId, name: item.workEffortName || item.workEffortId, rootWorkEffortId: root,
            projectName: rootItem?.workEffortName || root, closed: ['WeComplete', 'WeClosed', 'WeCancelled'].includes(item.statusId)}
    }
    cache.item[text] = result
    return result
}
const typeOf = (value) => {
    const text = String(value || '').trim()
    if (!text) return {enumId: null}
    if (!cache.type) {
        cache.type = {}
        for (const row of ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', 'WorkType').useCache(true).list()) {
            cache.type[String(row.enumId).toLowerCase()] = row
            if (row.description) cache.type[String(row.description).toLowerCase()] = row
        }
    }
    const row = cache.type[text.toLowerCase()]
    return row ? {enumId: row.enumId, label: row.description || row.enumId} : {enumId: null, warning: L('No work type ${type}; left empty', {type: text})}
}
const policyOf = (person) => {
    if (!(person in cache.policy)) cache.policy[person] = ec.service.sync().name('mantle.work.TimesheetServices.get#TimesheetPolicy')
            .parameters({partyId: person}).call()?.policy || {}
    return cache.policy[person]
}
const weekAccess = (person, day) => {
    const policy = policyOf(person)
    const range = ec.service.sync().name('mantle.work.TimesheetServices.get#WeekRange').parameters({date: day, weekStart: policy.weekStart || 1}).call()
    const key = person + '|' + range.weekStartDay
    if (!(key in cache.access)) {
        const sheet = ec.service.sync().name('mantle.work.TimesheetServices.get#PartyTimesheet').parameters({partyId: person, date: range.weekStartDay, make: false}).call() || {}
        // the user's rights, so authorization back on for the access (it reads the user, not the records)
        cache.access[key] = ec.service.sync().name('mantle.work.TimesheetServices.get#TimesheetAccess').parameters(sheet.timesheetId
                ? {timesheetId: sheet.timesheetId} : {partyId: person, date: range.weekStartDay}).call() || {}
    }
    return cache.access[key]
}
const nameOf = (person) => {
    const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', person).one()
    return party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || person) : person
}
const dayStart = (day) => Number(String(ec.l10n.parseTimestamp(day + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS')))
const today = ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
const cell = (values, target) => indexOf[target] == null ? '' : String(values[indexOf[target]] ?? '').trim()
// a time of day as minutes, or a date and time as [day, minutes]
const timeOf = (text) => {
    const t = String(text || '').trim()
    let m = /^(\d{4}-\d{2}-\d{2})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?/.exec(t)
    if (m) return {day: m[1], minutes: Number(m[2]) * 60 + Number(m[3])}
    m = /^(\d{1,2}):(\d{2})(?::(\d{2}))?\s*([AaPp][Mm])?$/.exec(t)
    if (!m) return null
    let h = Number(m[1])
    if (m[4]) { const pm = m[4].toLowerCase() === 'pm'; if (h === 12) h = pm ? 12 : 0; else if (pm) h += 12 }
    if (h > 24 || Number(m[2]) > 59) return null
    return {day: null, minutes: h * 60 + Number(m[2])}
}
const hoursOf = (text) => {
    const t = String(text || '').trim()
    if (!t) return null
    const m = /^(\d+):(\d{2})(?::(\d{2}))?$/.exec(t)
    if (m) return Number(m[1]) + Number(m[2]) / 60 + Number(m[3] || 0) / 3600
    const n = Number(t.replace(',', '.').replace(/\s*h(ours?)?$/i, ''))
    return Number.isNaN(n) ? NaN : n
}
const stacked = {}

// ===== the plan of each row
const planned = []
try {
    dataLines.forEach((values, i) => {
        const rowNumber = i + 2
        const problems = [], warnings = []
        const raw = {}
        headers.forEach((header, at) => { if (header) raw[header] = values[at] ?? '' })
        const row = {rowNumber: rowNumber, values: raw, problems: problems, warnings: warnings, action: 'create'}
        planned.push(row)
        try {
            // the person
            const person = personOf(cell(values, 'person'))
            if (person.error) problems.push(person.error)
            else if (!person.partyId) problems.push(L('No person: the file has none and you have no party'))
            else { row.partyId = person.partyId; row.personName = nameOf(person.partyId) }
            // the day and the times
            const start = timeOf(cell(values, 'start'))
            const end = timeOf(cell(values, 'end'))
            let day = cell(values, 'date')
            const dayMatch = /^(\d{4}-\d{2}-\d{2})/.exec(day)
            day = dayMatch ? dayMatch[1] : (start?.day || null)
            if (!day) { problems.push(cell(values, 'date') ? L('The date ${date} is not yyyy-MM-dd', {date: cell(values, 'date')}) : L('No date')); return }
            row.day = day
            const base = dayStart(day)
            let hours = hoursOf(cell(values, 'hours'))
            if (Number.isNaN(hours)) { problems.push(L('The hours ${hours} are not a number', {hours: cell(values, 'hours')})); hours = null }
            let from = null, thru = null
            if (start && end) {
                from = base + start.minutes * 60000
                thru = (end.day ? dayStart(end.day) : base) + end.minutes * 60000
                if (thru <= from) thru += 86400000
                if (hours == null) hours = (thru - from) / 3600000
            } else if (start) from = base + start.minutes * 60000
            if (hours == null) { if (!cell(values, 'hours')) problems.push(L('No hours, nor start and end')); return }
            if (!(hours > 0) || hours > 24) { problems.push(L('The hours are more than 0 and at most 24')); return }
            const policy = row.partyId ? policyOf(row.partyId) : {}
            const step = Number(policy.minHours || 0.25)
            let rounded = Math.round(hours / step) * step
            if (rounded === 0) rounded = step
            rounded = Math.round(rounded * 100) / 100
            if (Math.abs(rounded - hours) > 0.004) warnings.push(L('${hours} h rounded to ${rounded} h (the smallest entry)', {hours: Math.round(hours * 100) / 100, rounded}))
            row.hours = rounded
            if (from == null) {
                const key = (row.partyId || '') + '|' + day
                from = stacked[key] ?? base + 9 * 3600000
            }
            thru = from + rounded * 3600000
            if (thru > base + 2 * 86400000) { problems.push(L('The entry runs past the next day')); return }
            stacked[(row.partyId || '') + '|' + day] = thru
            row.fromDate = from; row.thruDate = thru
            // the work item, else the project
            const itemText = cell(values, 'item') || cell(values, 'project')
            if (itemText) {
                const item = itemOf(itemText)
                if (item?.error) problems.push(item.error)
                else if (item) {
                    row.workEffortId = item.workEffortId; row.itemName = item.name; row.rootWorkEffortId = item.rootWorkEffortId; row.projectName = item.projectName
                    if (item.closed) warnings.push(L('${key} is closed', {key: item.workEffortId}))
                }
            } else if (policy.needItem) problems.push(L('No work item: the policy requires one'))
            // the work type, billable, the comment
            const type = typeOf(cell(values, 'workType'))
            if (type.warning) warnings.push(type.warning)
            row.workTypeEnumId = type.enumId; row.workTypeLabel = type.label || ''
            const billText = cell(values, 'billable').toLowerCase()
            if (['', 'y', 'yes', 'true', '1', 'billable'].includes(billText)) row.billable = true
            else if (['n', 'no', 'false', '0', 'not billable', 'non-billable', 'nonbillable'].includes(billText)) row.billable = false
            else { row.billable = true; warnings.push(L('Billable ${value} not read; billable', {value: cell(values, 'billable')})) }
            row.comments = cell(values, 'comment') || null
            if (row.comments && row.comments.length > 4000) { row.comments = row.comments.substring(0, 4000); warnings.push(L('The comment was cut to 4000 characters')) }
            if (!row.partyId) return
            // the week: the user may change it, it is not locked, the day is allowed
            if (policy.future === false && day > today) problems.push(L('Time is not logged on future days'))
            const access = weekAccess(row.partyId, day)
            if (!access.canEdit) problems.push(access.locked ? L('The week of ${day} is submitted: its time is locked', {day}) : L('You may not log time for ${name}', {name: row.personName}))
            if (problems.length) return
            // an entry there already: skipped
            let existing = ec.entity.find('mantle.work.time.TimeEntry').condition('partyId', row.partyId).condition('fromDate', new Date(from))
            existing = row.workEffortId ? existing.condition('workEffortId', row.workEffortId) : existing.condition('workEffortId', 'is-null', null)
            if (existing.count() > 0) { row.action = 'skip'; warnings.push(L('Already logged: an entry starting then is there')) }
        } catch (err) {
            problems.push(String(err && err.message ? err.message : err))
            ec.message.clearErrors()
        } finally {
            if (problems.length) row.action = 'fail'
        }
    })
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
for (const row of planned) {
    counts[row.action] = (counts[row.action] || 0) + 1
    if (row.warnings.length) counts.warned++
}
const fmt = (millis, pattern) => millis == null ? '' : ec.l10n.format(String(millis), pattern)
const shape = (row) => ({rowNumber: row.rowNumber, day: row.day || '', partyId: row.partyId || null, personName: row.personName || '',
    workEffortId: row.workEffortId || null, itemName: row.itemName || '', rootWorkEffortId: row.rootWorkEffortId || null, projectName: row.projectName || '',
    hours: row.hours ?? null, fromText: fmt(row.fromDate, 'HH:mm'), thruText: fmt(row.thruDate, 'HH:mm'), workTypeEnumId: row.workTypeEnumId || null,
    workTypeLabel: row.workTypeLabel || '', billable: row.billable !== false, comments: row.comments || '', action: row.action,
    problems: row.problems, warnings: row.warnings})
if (preview) { previewList = planned.slice(0, Math.max(1, Number(maxRows) || 50)).map(shape); return }

// ===== the rows, each in its own transaction
const progress = (done, finished) => {
    if (!progressUserId) return
    try {
        ec.makeNotificationMessage().topic('timeImportProgress').userId(progressUserId).message({progressKey: progressKey || null, done: done,
            total: planned.length, createdCount, skippedCount, failedCount, finished: finished}).send()
    } catch (err) { ec.logger.warn(`Time import progress for ${progressUserId} not sent: ${err}`) }
}
let done = 0, hoursSum = 0
for (const row of planned) {
    if (done > 0 && done % 25 === 0) progress(done, false)
    done++
    for (const warning of row.warnings) warningList.push({rowNumber: row.rowNumber, warning: warning})
    if (row.action === 'fail') {
        failedCount++
        const error = row.problems.join('; ')
        ec.logger.warn(`Time import of ${ec.user.userId}: row ${row.rowNumber} failed: ${error}`)
        failureList.push({rowNumber: row.rowNumber, error: error, values: row.values})
        resultList.push({rowNumber: row.rowNumber, action: 'fail', timeEntryId: null})
        continue
    }
    if (row.action === 'skip') { skippedCount++; resultList.push({rowNumber: row.rowNumber, action: 'skip', timeEntryId: null}); continue }
    try {
        const out = ec.service.sync().name('mantle.work.TimeServices.store#TimeEntry').parameters({partyId: row.partyId, workEffortId: row.workEffortId || null,
            fromDate: new Date(row.fromDate), thruDate: new Date(row.thruDate), hours: row.hours, rateTypeEnumId: row.billable === false ? 'RatpNoCharge' : 'RatpStandard',
            workTypeEnumId: row.workTypeEnumId || null, comments: row.comments || null}).requireNewTransaction(true).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        createdCount++
        hoursSum += Number(row.hours)
        resultList.push({rowNumber: row.rowNumber, action: 'create', timeEntryId: out?.timeEntryId || null})
    } catch (err) {
        const error = String(err && err.message ? err.message : err).trim()
        ec.message.clearErrors()
        ec.logger.warn(`Time import of ${ec.user.userId}: row ${row.rowNumber} failed: ${error}`)
        failedCount++
        failureList.push({rowNumber: row.rowNumber, error: error, values: row.values})
        resultList.push({rowNumber: row.rowNumber, action: 'fail', timeEntryId: null})
    }
}
hoursImported = Math.round(hoursSum * 100) / 100
progress(done, true)

entryList = []
if (recordEntityName !== 'mantle.work.effort.WorkEffort') return
const wanted = Array.from(kinds || []).map((kind) => String(kind).trim()).filter((kind) => kind)
if (wanted.length && !wanted.includes('time')) return
// a client contact gets no time in a record's timeline (impl-projects.md P10)
if (ec.user.userId && ec.user.hasPermission('PROJECT_CLIENT')) return
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    let find = ec.entity.find('mantle.work.time.TimeEntry').condition('workEffortId', recordId).condition('thruDate', 'is-not-null', null)
    if (beforeDate != null) find = find.condition('thruDate', 'less-than', beforeDate)
    const types = {}
    for (const type of ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', 'WorkType').useCache(true).list()) types[type.enumId] = type.description || type.enumId
    for (const entry of find.orderBy('-thruDate').limit(Math.max(1, Number(limit) || 50)).list()) {
        const hours = Number(String(entry.hours ?? 0))
        const label = entry.workTypeEnumId ? (types[entry.workTypeEnumId] || entry.workTypeEnumId) : ''
        entryList.push({kind: 'time', date: entry.thruDate, entryKey: entry.timeEntryId, authorPartyId: entry.partyId, authorUserId: null,
            title: ec.l10n.format(hours, '#,##0.##') + ' h' + (label ? ' · ' + label : ''), body: entry.comments || null, contentType: 'text/plain',
            statusId: null, hours: hours, workTypeEnumId: entry.workTypeEnumId || null, workTypeLabel: label, billable: entry.rateTypeEnumId !== 'RatpNoCharge',
            fromDate: entry.fromDate, thruDate: entry.thruDate, timeEntryId: entry.timeEntryId})
    }
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
